// image-lib has NO ambient fs (enforce denies it). It operates only through the
// handle the app hands it.
module.exports.run = function (handle, imagesDir, secretPath) {
  var out = [];
  // ambient fs must be denied:
  try { require('fs').readFileSync(secretPath); out.push('ambient=LEAKED'); }
  catch (e) { out.push('ambient=DENIED'); }
  // within the handle's grant -> allowed (possession):
  try { out.push('within=' + handle.readTextSync(imagesDir + '/logo.png').trim()); }
  catch (e) { out.push('within=DENIED'); }
  // outside the handle's grant -> denied:
  try { handle.readTextSync(secretPath); out.push('outside=LEAKED'); }
  catch (e) { out.push('outside=DENIED'); }
  // re-attenuate to cache/, then read within/outside the narrower scope:
  var cache = handle.scoped('cache');
  try { out.push('scoped-in=' + cache.readTextSync(imagesDir + '/cache/thumb.png').trim()); }
  catch (e) { out.push('scoped-in=DENIED'); }
  try { cache.readTextSync(imagesDir + '/logo.png'); out.push('scoped-out=LEAKED'); }
  catch (e) { out.push('scoped-out=DENIED'); }
  return out.join(' ');
};
